// Get agent response
let agentOutput = $input.item.json.output || $input.item.json;

// Try to parse if it's a string
if (typeof agentOutput === 'string') {
  try {
    agentOutput = JSON.parse(agentOutput);
  } catch (e) {
    // If not valid JSON, wrap it
    agentOutput = {
      response: agentOutput
    };
  }
}

// Ensure required fields exist
const response = {
  response: agentOutput.response || "I processed your request.",
  data: agentOutput.data || null,
  visualization: agentOutput.visualization || null,
  sql: agentOutput.sql || null
};

// Clean up null fields
Object.keys(response).forEach(key => {
  if (response[key] === null) {
    delete response[key];
  }
});

return [{ json: response }];
